import fs from'node:fs';import path from'node:path';import assert from'node:assert/strict';import{execFileSync}from'node:child_process';import{hash,json}from'./bounded-source-hash-20261026.mjs';
export function clonePinnedWebsite({stage,parentFile,parentSha256}){assert(/^[a-f0-9]{64}$/.test(parentSha256));assert.equal(hash(parentFile),parentSha256);const parent=json(parentFile),site=stage+'/website',ix=json('CURRENT_CHECKPOINT.json');assert(path.resolve(stage).startsWith(path.resolve('F:/VisibleMedicine/staging')+path.sep));assert(!fs.existsSync(stage));assert.deepEqual(ix.activeWork.current.activeExecutionSessions,[]);assert.equal(ix.activeWork.current.ownerPreviewPolicy.restartPermitted,false);assert.equal(ix.goal.requirements,71);assert.equal(ix.goal.optionalIdeas,8);const git=(...a)=>execFileSync('git',a,{encoding:'utf8',windowsHide:true,env:{...process.env,GIT_NO_REPLACE_OBJECTS:'1',GIT_OPTIONAL_LOCKS:'0'}}).trim();for(const[p,h]of[['F:/VisibleMedicine/website','b953ff3f5f1891599cb6e91cb91311d9d6006270'],['F:/VisibleMedicine/atlas','6d7a356ae949e13f2ff4bf1fec610ee6ae7762c1'],[parent.atlas,parent.atlasHead]])assert.equal(git('-C',p,'rev-parse','HEAD'),h);assert.equal(git('-C',parent.atlas,'status','--porcelain'),'');fs.mkdirSync(stage);git('clone','--shared','--no-checkout','--','F:/VisibleMedicine/website',site);git('-C',site,'config','--local','core.autocrlf','false');git('-C',site,'read-tree','HEAD');for(const r of parent.sourceRows){assert.equal(hash(parent.website+'/'+r.path),r.sha256,r.path);const to=path.resolve(site,r.path);assert(to.startsWith(path.resolve(site)+path.sep));fs.mkdirSync(path.dirname(to),{recursive:true});fs.copyFileSync(parent.website+'/'+r.path,to,fs.constants.COPYFILE_EXCL);}fs.symlinkSync(fs.realpathSync.native(parent.website+'/node_modules'),site+'/node_modules','junction');fs.symlinkSync(parent.atlas,stage+'/atlas','junction');fs.writeFileSync(stage+'/PREPARATION.json',JSON.stringify({at:new Date().toISOString(),parent:{path:parentFile,sha256:parentSha256},website:site,atlas:parent.atlas,allParentSourceInitiallyExact:true,noPrivateStateCopied:true,normalPreviewChanged:false},null,2)+'\n',{flag:'wx'});return{parent,site};}
